            if left and reflected == right:
                known.update((ci, color) for color in set(left.values()))

    # For every demonstrated panel pair, reflect the populated pattern into
    # its mate. If both have markings, left-to-right is the completion direction.
    for ci, color in known:
        a0, a1 = col_spans[ci]
