 "content": "def transform(grid):
    """Infer a horizontal mirror relation between adjacent panels and complete it."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0]) if grid else 0
    if not h or not w:
        return g

    # Find solid separator rows/columns and the rectangular panels between them.
    hbars = [r for r, row in enumerate(g) if row[0] != 0 and all(v == row[0] for v in row)]
    vbars = [c for c in range(w) if g[0][c] != 0 and all(g[r][c] == g[0][c] for r in range(h))]

    def spans(size, bars):
        out, start = [], 0
        for b in bars:
            if start < b:
                out.append((start, b))
            start = b + 1
        if start < size:
            out.append((start, size))
        return out

    rs, cs = spans(h, hbars), spans(w, vbars)

    def cells(rspan, cspan, color):
        r0, r1 = rspan
        c0, c1 = cspan
        return {(r-r0, c-c0) for r in range(r0, r1) for c in range(c0, c1)
                if g[r][c] == color}

    def reflect(shape, width):
        return {(r, width-1-c) for r, c in shape}

    # Learn a color/panel pairing from a row in which both panels show matching
    # reflected markings (possibly with one panel only partially drawn).
    relations = set()
    for ci in range(len(cs)-1):
        a0, a1 = cs[ci]
        b0, b1 = cs[ci+1]
        width = a1-a0
        if width != b1-b0:
            continue
        for ri, rspan in enumerate(rs):
            for color in {g[r][c] for r in range(*rspan) for c in range(a0, a1) if g[r][c] != 0}:
                left = cells(rspan, cs[ci], color)
                right = cells(rspan, cs[ci+1], color)
                if left and right:
                    ml = reflect(left, width)
                    mr = reflect(right, width)
                    if ml == right or ml.issuperset(right) or mr.issuperset(left):
                        relations.add((ci, color))

    # Complete each learned relation in every panel row. Existing unrelated
    # markings are retained; only copy when one side is empty or compatible.
    for ci, color in relations:
        a0, a1 = cs[ci]
        b0, b1 = cs[ci+1]
        width = a1-a0
        if width != b1-b0:
            continue
        for rspan in rs:
            r0, r1 = rspan
            left = cells(rspan, cs[ci], color)
            right = cells(rspan, cs[ci+1], color)
            if left and not right:
                for rr, cc in reflect(left, width):
                    g[r0+rr][b0+cc] = color
            elif right and not left:
                for rr, cc in reflect(right, width):
                    g[r0+rr][a0+cc] = color
            elif left and right:
                ml, mr = reflect(left, width), reflect(right, width)
                if ml.issuperset(right):
                    for rr, cc in ml:
                        g[r0+rr][b0+cc] = color
                elif mr.issuperset(left):
                    for rr, cc in mr:
                        g[r0+rr][a0+cc] = color
    return g
